import { describe, it, expect, vi, beforeEach } from 'vitest';
import { mount, flushPromises } from '@vue/test-utils';
import { createPinia, setActivePinia } from 'pinia';
import { useAuthStore } from '../src/stores/auth';
import MySqlCustomerListView from '../src/views/mysqlcustomer/MySqlCustomerListView.vue';
import { mySqlCustomerApi } from '../src/api/mysql-customer';
import { dictionaryApi } from '../src/api/enterprise';
import type { MySqlCustomer } from '../src/types/mysql-customer';
import { epStubs, platformStubs } from './stubs';

const stubs = { ...epStubs(), ...platformStubs() };

const rows: MySqlCustomer[] = [ { id: '1', code: 'v', name: 'v', phone: 'v', status: 'v', level: 'v', departmentId: '1', createdBy: '1', createdAt: '2026-08-16T00:00:00', updatedAt: '2026-08-16T00:00:00' } ];

function seed(permissions: string[]): void {
  const pinia = createPinia();
  setActivePinia(pinia);
  const auth = useAuthStore(pinia);
  auth.$patch({ currentUser: { id: '1', username: 'u', departmentId: null, permissions } });
  localStorage.clear();
}

function mockApis(): void {
  vi.spyOn(mySqlCustomerApi, 'page').mockResolvedValue({ items: rows, total: 1, page: 1, size: 20 });
  vi.spyOn(dictionaryApi, 'itemsByCode').mockResolvedValue([]);
}

describe('MySqlCustomerListView', () => {
  beforeEach(() => { vi.restoreAllMocks(); });

  it('loads rows via the API', async () => {
    seed(['demo_customer:item:read']);
    mockApis();
    await mount(MySqlCustomerListView, { global: { stubs } });
    await flushPromises();
    expect(mySqlCustomerApi.page).toHaveBeenCalled();
  });

  it('shows error state when list fails (no white screen)', async () => {
    seed(['demo_customer:item:read']);
    vi.spyOn(mySqlCustomerApi, 'page').mockRejectedValue(new Error('boom'));
    vi.spyOn(dictionaryApi, 'itemsByCode').mockResolvedValue([]);
    const wrapper = await mount(MySqlCustomerListView, { global: { stubs } });
    await flushPromises();
    expect(wrapper.html().length).toBeGreaterThan(0);
  });
});
